/**
 * Thailand province outlines as pre-projected SVG paths + the projection
 * used to bake them. GENERATED ONCE from public GeoJSON (apisit/thailand.json,
 * 77 provinces) via scripts/gen_thailand_geo.py — do not hand-edit. Fully
 * offline: no map tiles, no runtime network, satisfies the strict nginx CSP
 * (img-src 'self').
 *
 * projectLngLat() below MUST stay identical to the Python projection that
 * produced these paths, so plot markers land in the right place on the map.
 */
export const VIEW_WIDTH = 545.8;
export const VIEW_HEIGHT = 1000.0;
const MIN_LNG = 97.35140100100011;
const MAX_LNG = 105.65099776200009;
const MIN_LAT = 5.629890035000074;
const MAX_LAT = 20.445006409000143;
const LON_SCALE = 0.9742228298437415;
const SCALE = 67.4986260489293;

/** lng/lat (WGS84) -> SVG viewBox coordinates. Baked identically to the
 * generator so markers align with the province outlines. */
export function projectLngLat(lng: number, lat: number): { x: number; y: number } {
  return {
    x: (lng - MIN_LNG) * LON_SCALE * SCALE,
    y: (MAX_LAT - lat) * SCALE,
  };
}

/** True when a coordinate falls inside Thailand's bounding box (a cheap
 * guard so an out-of-range plot does not render off-canvas). */
export function isWithinThailand(lng: number, lat: number): boolean {
  return lng >= MIN_LNG && lng <= MAX_LNG && lat >= MIN_LAT && lat <= MAX_LAT;
}

